const people=['Анна Смирнова','Дмитрий Волков','Мария Козлова','Илья Петров'];
const raw=[['Поставка серверного оборудования','ГБУ «Мосинфосистемы»',18.4,'Подготовка',17,0,'44-ФЗ'],['Модернизация сети передачи данных','АО «Региональные сети»',32.7,'Подготовка',18,1,'223-ФЗ'],['Техническое обслуживание ИТ-инфраструктуры','ФГБУ «Центр цифровизации»',9.6,'Подготовка',21,2,'44-ФЗ'],['Поставка рабочих станций','ПАО «Энергокомплекс»',14.2,'Подана',14,3,'223-ФЗ'],['Внедрение системы электронного документооборота','Администрация городского округа',24.8,'Оценка',10,0,'44-ФЗ'],['Поставка сетевого оборудования','АО «Транспортные решения»',12.5,'Победа',5,1,'223-ФЗ'],['Сопровождение информационной системы','ГБУ «Городской сервис»',7.8,'Победа',3,2,'44-ФЗ'],['Поставка программных лицензий','ООО «Промышленная группа»',6.4,'Проигран',2,3,'Коммерческий']];
let month=9;const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n);const initials=n=>n.split(' ').map(x=>x[0]).join('');const $=s=>document.querySelector(s);function data(){return raw.map((r,i)=>({id:i,title:r[0],client:r[1],value:Math.round(r[2]*(month===9?1:month===8?.83:.71)*10)/10,status:month===9?r[3]:i%3===0?'Победа':i%3===1?'Проигран':'Победа',day:r[4],person:r[5],law:r[6],month}));}function filtered(){const q=$('#search').value.toLowerCase();return data().filter(t=>($('#status').value==='all'||t.status===$('#status').value)&&`${t.title} ${t.client}`.toLowerCase().includes(q));}
function render(){const d=data(),active=d.filter(t=>!['Победа','Проигран'].includes(t.status)),won=d.filter(t=>t.status==='Победа'),closed=d.length-active.length,rate=Math.round(won.length/closed*100);$('#kpis').innerHTML=[['В работе',active.length,'тендеров',`${money(active.reduce((s,t)=>s+t.value,0))} млн ₽ в открытом портфеле`],['Выиграно',money(won.reduce((s,t)=>s+t.value,0)),'млн ₽',`${won.length} процедуры завершились победой`],['Доля побед',rate,'%',`${won.length} из ${closed} завершённых процедур`],['Средняя победа',money(won.reduce((s,t)=>s+t.value,0)/won.length),'млн ₽','По НМЦК выигранных процедур']].map((k,i)=>`<article class="kpi"><div class="kpi-title">${k[0]}<span class="kpi-icon">${['▤','↗','◴','◇'][i]}</span></div><div class="kpi-value">${k[1]} <small>${k[2]}</small></div><div class="kpi-meta">${k[3]}</div></article>`).join('');$('#funnel-total').textContent=`${d.length} процедур`;$('#funnel').innerHTML=['Подготовка','Подана','Оценка','Победа'].map(s=>{const n=d.filter(t=>t.status===s).length;return `<div class="funnel-row"><span>${s}</span><div class="bar-track"><div class="bar" style="width:${n/d.length*100}%"></div></div><b>${n}</b></div>`}).join('');$('#open-value').textContent=money(active.reduce((s,t)=>s+t.value,0))+' млн ₽';const due=active.filter(t=>t.status==='Подготовка').sort((a,b)=>a.day-b.day);$('#alert-count').textContent=due.length;$('#deadline-list').innerHTML=due.length?due.map(t=>`<div class="deadline" role="button" tabindex="0" data-id="${t.id}"><div class="daybox"><b>${t.day}</b><small>СЕН</small></div><div class="deadline-copy"><strong>${t.title}</strong><p>${people[t.person]} · до 18:00</p></div><span class="due">${t.day===17?'Завтра':`Через ${t.day-16} дн.`}</span></div>`).join(''):'<div class="empty">Нет предстоящих сроков в этом месяце</div>';$('#team-list').innerHTML=people.map((p,i)=>{const n=active.filter(t=>t.person===i).length;return `<div class="team-person"><div class="owner"><span class="avatar">${initials(p)}</span>${p}</div><div class="load-text"><span>${n} из 4 процедур</span><span>${Math.round(n/4*100)}%</span></div><div class="loadbar"><div style="width:${n/4*100}%"></div></div></div>`}).join('');renderRows();}
function renderRows(){const d=filtered();$('#record-count').textContent=data().length;$('#table-info').textContent=`Показано ${d.length} из ${data().length} процедур`;$('#rows').innerHTML=d.length?d.map(t=>`<tr><td><button class="tender-link" data-id="${t.id}">${t.title}</button><small>${t.client} · ${t.law}</small></td><td><b>${money(t.value)} млн ₽</b></td><td><span class="status s-${t.status}">${t.status}</span></td><td>${t.day.toString().padStart(2,'0')}.${String(month).padStart(2,'0')}.2026<small>18:00 МСК</small></td><td><div class="owner"><span class="avatar">${initials(people[t.person])}</span>${people[t.person].split(' ')[0]} ${people[t.person].split(' ')[1][0]}.</div></td><td><button class="tender-link" data-id="${t.id}" aria-label="Открыть ${t.title}">↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Тендеры не найдены. Измените запрос или статус.</td></tr>';}
function show(id){const t=data().find(t=>t.id===Number(id));$('#detail-content').innerHTML=`<span class="status s-${t.status}">${t.status}</span><h2>${t.title}</h2><p>${t.client}</p><div class="detail-grid"><div><small>НМЦК</small><strong>${money(t.value)} млн ₽</strong></div><div><small>Подача заявки до</small><strong>${t.day}.${String(month).padStart(2,'0')}.2026 · 18:00</strong></div><div><small>Ответственный</small><strong>${people[t.person]}</strong></div><div><small>Тип закупки</small><strong>${t.law}</strong></div></div><p>Демонстрационная процедура. Суммы показаны по начальной максимальной цене, а не по фактической стоимости контракта.</p>`;$('#detail').showModal();}
document.addEventListener('click',e=>{const a=e.target.closest('[data-id]');if(a)show(a.dataset.id);const tab=e.target.closest('[data-month]');if(tab){month=Number(tab.dataset.month);document.querySelectorAll('[data-month]').forEach(b=>b.classList.toggle('selected',b===tab));render();}});document.addEventListener('keydown',e=>{if(e.target.matches('.deadline')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();show(e.target.dataset.id);}});$('#search').addEventListener('input',renderRows);$('#status').addEventListener('change',renderRows);$('.close').onclick=$('#detail-close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#export').onclick=()=>{const rows=[['Тендер','Заказчик','НМЦК, руб.','Статус','Срок подачи, МСК','Ответственный','Тип закупки'],...filtered().map(t=>[t.title,t.client,t.value*1000000,t.status,`${t.day}.${month}.2026 18:00`,people[t.person],t.law])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`Тендеры-${month}-2026.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#toast').textContent='Отчёт по выбранным тендерам скачан';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000);};render();
